  "home.testimonials.title1": { ar: "موثوق من ", fr: "Approuvé par ", en: "Trusted by " },
  "home.testimonials.titleHighlight": { ar: "التجار التونسيين", fr: "les commerçants tunisiens", en: "Tunisian merchants" },
  "home.testimonials.quote1": { ar: "خفضت يقين نسبة المرتجعات من 28% إلى 11% في أسبوعين فقط. التحقق الهاتفي غيّر قواعد اللعبة للتجارة الإلكترونية التونسية.", fr: "YAKEEN a réduit notre RTO de 28% à 11% en deux semaines. La vérification téléphonique change la donne.", en: "YAKEEN cut our RTO rate from 28% to 11% in just two weeks. The phone verification is a game-changer for Tunisian e-commerce." },
  "home.testimonials.author1": { ar: "أحمد بن علي", fr: "Ahmed Ben Ali", en: "Ahmed Ben Ali" },
  "home.testimonials.role1": { ar: "الرئيس التنفيذي، MegaStore.tn", fr: "PDG, MegaStore.tn", en: "CEO, MegaStore.tn" },
  "home.testimonials.quote2": { ar: "كنا نتحقق يدوياً من كل طلب فوق 50 دينار. الآن الذكاء الاصطناعي يفعلها بالميلي ثانية. وفرنا 40+ ساعة أسبوعياً.", fr: "Nous vérifiions manuellement chaque commande de plus de 50 TND. Maintenant l'IA le fait en millisecondes.", en: "We were manually verifying every order over 50 TND. Now AI does it in milliseconds. Saved us 40+ hours per week." },
  "home.testimonials.author2": { ar: "سارة المنصوري", fr: "Sarra Mansouri", en: "Sarra Mansouri" },
  "home.testimonials.role2": { ar: "قائد العمليات، ShopTunisia", fr: "Responsable des opérations, ShopTunisia", en: "Operations Lead, ShopTunisia" },
  "home.testimonials.quote3": { ar: "درجة الثقة دقيقة بشكل لا يصدق. يمكنك رؤية الطلبات التي ستفشل قبل شحنها.", fr: "Le score de confiance est incroyablement précis. Vous voyez les commandes qui échoueront avant l'expédition.", en: "The trust score is incredibly accurate. You can literally see which orders will fail before they ship." },
  "home.testimonials.author3": { ar: "كريم الجبالي", fr: "Karim Jebali", en: "Karim Jebali" },
  "home.testimonials.role3": { ar: "المؤسس، CartExpress", fr: "Fondateur, CartExpress", en: "Founder, CartExpress" },

