  /* Social Sellers */
  "socialSellers.title": { ar: "فيسبوك وإنستغرام — الطلبات من المحادثة", fr: "Facebook et Instagram — Commandes par conversation", en: "Facebook & Instagram — Orders from Conversations" },
  "socialSellers.desc1": { ar: "اربط", fr: "Connectez votre", en: "Connect your" },
  "socialSellers.fb": { ar: "صفحة فيسبوك", fr: "Page Facebook", en: "Facebook Page" },
  "socialSellers.desc2": { ar: "الخاصة بك؛ رسائل", fr: "; les messages", en: "; professional" },
  "socialSellers.ig": { ar: "إنستغرام", fr: "Instagram", en: "Instagram" },
  "socialSellers.desc3": { ar: "المهنية المربوطة بنفس الصفحة تخدم تلقائياً. بعد الربط، تقدر تضبط شنوة يسألها البوت للزبون (مقاس، لون، عنوان…) والطلب يوصل لقائمة طلباتك في يقين.", fr: "professionnels liés à la même page sont automatiquement pris en charge. Après connexion, configurez ce que le bot demande au client (taille, couleur, adresse…) et la commande arrive dans votre liste YAKEEN.", en: "messages linked to the same page are auto-served. After connecting, set what the bot asks the customer (size, color, address…) and the order arrives in your YAKEEN order list." },
  "socialSellers.connectCard": { ar: "ربط صفحة فيسبوك", fr: "Connecter une page Facebook", en: "Connect Facebook Page" },
  "socialSellers.connectDesc": { ar: "اضغط الزر واتبع تسجيل الدخول بفيسبوك. أول مرة قد يطلب منك فيسبوك صلاحيات لصفحتك—هذا طبيعي. إن واجهت مشكلة، رجاءً تصل بالدعم لأن أحياناً يلزم إكمال إعداد من طرف منصتنا.", fr: "Cliquez sur le bouton et suivez la connexion Facebook. La première fois, Facebook peut demander des autorisations — c'est normal. En cas de problème, contactez le support car une configuration peut être nécessaire.", en: "Click the button and follow Facebook login. The first time, Facebook may ask for page permissions — this is normal. If you encounter issues, please contact support as setup may be required on our end." },
  "socialSellers.securityWarning": { ar: "الربط الآمن للصفحة يحتاج تجهيزاً من جهة الخادم. إن بقى الزر معطّلاً، راسل الدعم—ما تحتاجش تفهم التفاصيل التقنية.", fr: "La connexion sécurisée nécessite une configuration serveur. Si le bouton reste désactivé, contactez le support.", en: "Secure page connection requires server-side setup. If the button remains disabled, contact support." },
  "socialSellers.connectButton": { ar: "ربط صفحة فيسبوك", fr: "Connecter une page Facebook", en: "Connect Facebook Page" },
