  "plugins.pageTitle": { ar: "الإضافات", fr: "Plugins", en: "Plugins" },
  "plugins.pageSubtitle": { ar: "تثبيت وإدارة الإضافات والتكاملات", fr: "Installer et gérer les plugins et intégrations", en: "Install and manage plugins and integrations" },
  "plugins.available": { ar: "إضافات متاحة", fr: "Plugins disponibles", en: "Available plugins" },
