  "plugins.minutes": { ar: "دقائق للتفعيل", fr: "Minutes pour activer", en: "Minutes to activate" },
  "plugins.whyTitle": { ar: "لماذا يقين؟", fr: "Pourquoi YAKEEN?", en: "Why YAKEEN?" },
  "plugins.whySubtitle": { ar: "تكامل سريع، نتائج واضحة، ودعم محلي.", fr: "Intégration rapide, résultats clairs, support local.", en: "Fast integration, clear results, local support." },
  "plugins.chooseTitle": { ar: "اختر إضافة متجرك", fr: "Choisissez votre plugin", en: "Choose your store plugin" },
  "plugins.chooseSubtitle": { ar: "تكاملات رسمية وموثوقة. تفعيل خلال دقائق.", fr: "Intégrations officielles et fiables. Activation en quelques minutes.", en: "Official, reliable integrations. Activate in minutes." },
