  "plugins.comingSoonSubtitle": { ar: "تكاملات ومنتجات جديدة قيد الإعداد.", fr: "Nouvelles intégrations et produits en préparation.", en: "New integrations and products in preparation." },
  "plugins.ctaTitle": { ar: "جاهز للبدء؟", fr: "Prêt à commencer?", en: "Ready to start?" },
  "plugins.ctaSubtitle": { ar: "أنشئ حسابك مجاناً، اختر الإضافة المناسبة لمتجرك، وابدأ التحقق من المشترين اليوم.", fr: "Créez un compte gratuit, choisissez le plugin adapté, et commencez à vérifier vos clients aujourd'hui.", en: "Create a free account, choose the right plugin, and start verifying customers today." },
  "plugins.heroTitle": { ar: "الإضافات التي تجعل متجرك أكثر أماناً", fr: "Les plugins qui sécurisent votre boutique", en: "Plugins that make your store safer" },
  "plugins.browsePlugins": { ar: "تصفح الإضافات", fr: "Parcourir les plugins", en: "Browse plugins" },
  "plugins.registerFree": { ar: "إنشاء حساب مجاني", fr: "Créer un compte gratuit", en: "Create free account" },
