  "plugins.socialBadge": { ar: "بدون موقع إلكتروني", fr: "Sans site web", en: "No website needed" },
  "plugins.shopifyName": { ar: "تكامل Shopify", fr: "Intégration Shopify", en: "Shopify Integration" },
  "plugins.shopifyDesc": { ar: "ربط تلقائي مع متجرك على Shopify. تحقق من كل طلب قبل الشحن وحساب درجة الثقة والمخاطر في الوقت الفعلي.", fr: "Connexion automatique avec votre boutique Shopify. Vérification de chaque commande avant expédition.", en: "Automatic connection with your Shopify store. Verify every order before shipping." },
  "plugins.wooName": { ar: "تكامل WooCommerce", fr: "Intégration WooCommerce", en: "WooCommerce Integration" },
  "plugins.wooDesc": { ar: "إضافة جاهزة لمتاجر ووردبريس. تقليل الارتجاعات والاحتيال مع تقارير مفصلة عن سلوك المشترين.", fr: "Plugin prêt pour les boutiques WordPress. Réduction des retours et fraudes avec des rapports détaillés.", en: "Ready plugin for WordPress stores. Reduce returns and fraud with detailed customer reports." },
  "plugins.apiName": { ar: "تكامل API", fr: "Intégration API", en: "API Integration" },
  "plugins.apiDesc": { ar: "ربط أي منصة أو تطبيق عبر API. مرن وقوي للتجار والمطورين والأنظمة الداخلية.", fr: "Connectez toute plateforme via API. Flexible et puissant pour marchands et développeurs.", en: "Connect any platform via API. Flexible and powerful for merchants and developers." },
  "plugins.socialName": { ar: "فيسبوك وإنستغرام", fr: "Facebook et Instagram", en: "Facebook & Instagram" },
  "plugins.socialDesc": { ar: "بيع عبر ماسنجر صفحة فيسبوك أو رسائل إنستغرام: يربط العملاء بالمنتج ويجمع الطلبات تلقائياً في يقين.", fr: "Vendez via Messenger ou Instagram DM: connectez les clients au produit et collectez les commandes automatiquement.", en: "Sell via Facebook Messenger or Instagram DM: connect customers to products and collect orders automatically in YAKEEN." },
